class FolioRow extends DataClass implements Insertable<FolioRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String? createdBy;
  final String? updatedBy;
  final String? originDeviceId;
  final int? changeSeq;
  final SyncState syncState;
  final String hotelId;
  final String number;
  final FolioType type;
  final FolioStatus status;
  final String? reservationRoomId;
  final String? guestId;
  final String? companyId;
  final String? restaurantTableId;

  /// Totaux tenus a jour a chaque ecriture, en francs CFA, entiers.
  ///
  /// Redondants avec la somme des lignes, mais un ecran de tablette doit
  /// afficher un solde immediatement : recalculer l'agregat du folio a chaque
  /// rafraichissement rendrait la liste des chambres visiblement lente.
  final int chargesTotal;
  final int paymentsTotal;
  final int balance;
  final DateTime? openedAt;
  final DateTime? closedAt;
  final String? notes;
  const FolioRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.createdBy,
    this.updatedBy,
    this.originDeviceId,
    this.changeSeq,
    required this.syncState,
    required this.hotelId,
    required this.number,
    required this.type,
    required this.status,
    this.reservationRoomId,
    this.guestId,
    this.companyId,
    this.restaurantTableId,
    required this.chargesTotal,
    required this.paymentsTotal,
    required this.balance,
    this.openedAt,
    this.closedAt,
    this.notes,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    if (!nullToAbsent || updatedBy != null) {
      map['updated_by'] = Variable<String>(updatedBy);
    }
    if (!nullToAbsent || originDeviceId != null) {
      map['origin_device_id'] = Variable<String>(originDeviceId);
    }
    if (!nullToAbsent || changeSeq != null) {
      map['change_seq'] = Variable<int>(changeSeq);
    }
    {
      map['sync_state'] = Variable<String>(
        $FoliosTable.$convertersyncState.toSql(syncState),
      );
    }
    map['hotel_id'] = Variable<String>(hotelId);
    map['number'] = Variable<String>(number);
    {
      map['type'] = Variable<String>($FoliosTable.$convertertype.toSql(type));
    }
    {
      map['status'] = Variable<String>(
        $FoliosTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || reservationRoomId != null) {
      map['reservation_room_id'] = Variable<String>(reservationRoomId);
    }
    if (!nullToAbsent || guestId != null) {
      map['guest_id'] = Variable<String>(guestId);
    }
    if (!nullToAbsent || companyId != null) {
      map['company_id'] = Variable<String>(companyId);
    }
    if (!nullToAbsent || restaurantTableId != null) {
      map['restaurant_table_id'] = Variable<String>(restaurantTableId);
    }
    map['charges_total'] = Variable<int>(chargesTotal);
    map['payments_total'] = Variable<int>(paymentsTotal);
    map['balance'] = Variable<int>(balance);
    if (!nullToAbsent || openedAt != null) {
      map['opened_at'] = Variable<DateTime>(openedAt);
    }
    if (!nullToAbsent || closedAt != null) {
      map['closed_at'] = Variable<DateTime>(closedAt);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    return map;
  }

  FoliosCompanion toCompanion(bool nullToAbsent) {
    return FoliosCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      createdBy: createdBy == null && nullToAbsent
          ? const Value.absent()
          : Value(createdBy),
      updatedBy: updatedBy == null && nullToAbsent
          ? const Value.absent()
          : Value(updatedBy),
      originDeviceId: originDeviceId == null && nullToAbsent
          ? const Value.absent()
          : Value(originDeviceId),
      changeSeq: changeSeq == null && nullToAbsent
          ? const Value.absent()
          : Value(changeSeq),
      syncState: Value(syncState),
      hotelId: Value(hotelId),
      number: Value(number),
      type: Value(type),
      status: Value(status),
      reservationRoomId: reservationRoomId == null && nullToAbsent
          ? const Value.absent()
          : Value(reservationRoomId),
      guestId: guestId == null && nullToAbsent
          ? const Value.absent()
          : Value(guestId),
      companyId: companyId == null && nullToAbsent
          ? const Value.absent()
          : Value(companyId),
      restaurantTableId: restaurantTableId == null && nullToAbsent
          ? const Value.absent()
          : Value(restaurantTableId),
      chargesTotal: Value(chargesTotal),
      paymentsTotal: Value(paymentsTotal),
      balance: Value(balance),
