class InvoiceRow extends DataClass implements Insertable<InvoiceRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String? createdBy;
  final String? updatedBy;
  final String? originDeviceId;
  final int? changeSeq;
  final SyncState syncState;
  final String hotelId;

  /// Nul tant que le serveur n'a pas attribue le numero definitif.
  final String? number;
  final String? provisionalNumber;
  final bool isProvisional;
  final String folioId;
  final String? guestId;
  final String? companyId;
  final InvoiceStatus status;
  final DateTime? issuedAt;
  final String? dueDate;

  /// Montants en francs CFA, entiers.
  final int subtotal;
  final int discountTotal;
  final int taxTotal;
  final int total;
  final String currency;

  /// Identite du destinataire, figee a l'emission.
  ///
  /// Si le client demenage l'annee suivante, une facture deja emise ne doit
  /// pas changer d'adresse : un document comptable est immuable.
  final String? billToName;
  final String? billToAddress;
  final String? billToTaxId;
  final String? pdfPath;
  final DateTime? cancelledAt;
  final String? cancelReason;
  const InvoiceRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.createdBy,
    this.updatedBy,
    this.originDeviceId,
    this.changeSeq,
    required this.syncState,
    required this.hotelId,
    this.number,
    this.provisionalNumber,
    required this.isProvisional,
    required this.folioId,
    this.guestId,
    this.companyId,
    required this.status,
    this.issuedAt,
    this.dueDate,
    required this.subtotal,
    required this.discountTotal,
    required this.taxTotal,
    required this.total,
    required this.currency,
    this.billToName,
    this.billToAddress,
    this.billToTaxId,
    this.pdfPath,
    this.cancelledAt,
    this.cancelReason,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    if (!nullToAbsent || updatedBy != null) {
      map['updated_by'] = Variable<String>(updatedBy);
    }
    if (!nullToAbsent || originDeviceId != null) {
      map['origin_device_id'] = Variable<String>(originDeviceId);
    }
    if (!nullToAbsent || changeSeq != null) {
      map['change_seq'] = Variable<int>(changeSeq);
    }
    {
      map['sync_state'] = Variable<String>(
        $InvoicesTable.$convertersyncState.toSql(syncState),
      );
    }
    map['hotel_id'] = Variable<String>(hotelId);
    if (!nullToAbsent || number != null) {
      map['number'] = Variable<String>(number);
    }
    if (!nullToAbsent || provisionalNumber != null) {
      map['provisional_number'] = Variable<String>(provisionalNumber);
    }
    map['is_provisional'] = Variable<bool>(isProvisional);
    map['folio_id'] = Variable<String>(folioId);
    if (!nullToAbsent || guestId != null) {
      map['guest_id'] = Variable<String>(guestId);
    }
    if (!nullToAbsent || companyId != null) {
      map['company_id'] = Variable<String>(companyId);
    }
    {
      map['status'] = Variable<String>(
        $InvoicesTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || issuedAt != null) {
      map['issued_at'] = Variable<DateTime>(issuedAt);
    }
    if (!nullToAbsent || dueDate != null) {
      map['due_date'] = Variable<String>(dueDate);
    }
    map['subtotal'] = Variable<int>(subtotal);
    map['discount_total'] = Variable<int>(discountTotal);
    map['tax_total'] = Variable<int>(taxTotal);
    map['total'] = Variable<int>(total);
    map['currency'] = Variable<String>(currency);
    if (!nullToAbsent || billToName != null) {
      map['bill_to_name'] = Variable<String>(billToName);
    }
    if (!nullToAbsent || billToAddress != null) {
      map['bill_to_address'] = Variable<String>(billToAddress);
    }
    if (!nullToAbsent || billToTaxId != null) {
      map['bill_to_tax_id'] = Variable<String>(billToTaxId);
    }
    if (!nullToAbsent || pdfPath != null) {
      map['pdf_path'] = Variable<String>(pdfPath);
    }
    if (!nullToAbsent || cancelledAt != null) {
      map['cancelled_at'] = Variable<DateTime>(cancelledAt);
    }
    if (!nullToAbsent || cancelReason != null) {
      map['cancel_reason'] = Variable<String>(cancelReason);
    }
    return map;
  }

