class MenuItemRow extends DataClass implements Insertable<MenuItemRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String? createdBy;
  final String? updatedBy;
  final String? originDeviceId;
  final int? changeSeq;
  final SyncState syncState;
  final String hotelId;
  final bool isActive;
  final String code;
  final String label;
  final String? description;
  final String menuCategoryId;

  /// Nul pour un article qui ne se prepare pas : droit d'entree en boite de
  /// nuit, acces piscine, bouteille vendue telle quelle. Une telle ligne ne
  /// produit aucun ticket de production, et le routage l'ignore.
  final String? prepStationId;

  /// Prix en francs CFA entiers, taux de taxe en points de base.
  final int price;
  final int taxRate;

  /// Rupture ponctuelle, distincte de `isActive` qui retire durablement
  /// l'article de la carte. Le serveur doit pouvoir signaler "plus de saumon
  /// ce soir" sans que le gerant ait a supprimer la ligne.
  final bool isAvailable;
  final int? preparationMinutes;

  /// Allergenes, en JSON.
  final String? allergens;
  final String? photoPath;
  final int sortOrder;
  const MenuItemRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.createdBy,
    this.updatedBy,
    this.originDeviceId,
    this.changeSeq,
    required this.syncState,
    required this.hotelId,
    required this.isActive,
    required this.code,
    required this.label,
    this.description,
    required this.menuCategoryId,
    this.prepStationId,
    required this.price,
    required this.taxRate,
    required this.isAvailable,
    this.preparationMinutes,
    this.allergens,
    this.photoPath,
    required this.sortOrder,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    if (!nullToAbsent || updatedBy != null) {
      map['updated_by'] = Variable<String>(updatedBy);
    }
    if (!nullToAbsent || originDeviceId != null) {
      map['origin_device_id'] = Variable<String>(originDeviceId);
    }
    if (!nullToAbsent || changeSeq != null) {
      map['change_seq'] = Variable<int>(changeSeq);
    }
    {
      map['sync_state'] = Variable<String>(
        $MenuItemsTable.$convertersyncState.toSql(syncState),
      );
    }
    map['hotel_id'] = Variable<String>(hotelId);
    map['is_active'] = Variable<bool>(isActive);
    map['code'] = Variable<String>(code);
    map['label'] = Variable<String>(label);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    map['menu_category_id'] = Variable<String>(menuCategoryId);
    if (!nullToAbsent || prepStationId != null) {
      map['prep_station_id'] = Variable<String>(prepStationId);
    }
    map['price'] = Variable<int>(price);
    map['tax_rate'] = Variable<int>(taxRate);
    map['is_available'] = Variable<bool>(isAvailable);
    if (!nullToAbsent || preparationMinutes != null) {
      map['preparation_minutes'] = Variable<int>(preparationMinutes);
    }
    if (!nullToAbsent || allergens != null) {
      map['allergens'] = Variable<String>(allergens);
    }
    if (!nullToAbsent || photoPath != null) {
      map['photo_path'] = Variable<String>(photoPath);
    }
    map['sort_order'] = Variable<int>(sortOrder);
    return map;
  }

  MenuItemsCompanion toCompanion(bool nullToAbsent) {
    return MenuItemsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
