      label: serializer.fromJson<String>(json['label']),
      description: serializer.fromJson<String?>(json['description']),
      menuCategoryId: serializer.fromJson<String>(json['menuCategoryId']),
      prepStationId: serializer.fromJson<String?>(json['prepStationId']),
      price: serializer.fromJson<int>(json['price']),
      taxRate: serializer.fromJson<int>(json['taxRate']),
      isAvailable: serializer.fromJson<bool>(json['isAvailable']),
      preparationMinutes: serializer.fromJson<int?>(json['preparationMinutes']),
