class PrinterRow extends DataClass implements Insertable<PrinterRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String? createdBy;
  final String? updatedBy;
  final String? originDeviceId;
  final int? changeSeq;
  final SyncState syncState;
  final String hotelId;
  final bool isActive;
  final String logicalName;
  final String label;
  final PrinterKind kind;
  final PrinterProtocol protocol;
  final String? host;
  final int? port;
  final String? devicePath;

  /// Largeur du papier thermique en millimetres : 58 ou 80 en pratique.
  /// Determine le nombre de caracteres par ligne du modele ESC/POS.
  final int? paperWidthMm;
  final String? location;
  final String? prepStationId;

  /// Supervision (regle R2). Sans battement de coeur, on ne decouvre qu'une
  /// imprimante est hors ligne qu'au moment ou un ticket est deja perdu et ou
  /// la cuisine attend une commande dont elle ignore l'existence.
  final bool isOnline;
  final DateTime? lastHeartbeatAt;
  final String? lastError;

  /// Repli automatique quand la cible est injoignable.
  final String? fallbackPrinterId;
  const PrinterRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.createdBy,
    this.updatedBy,
    this.originDeviceId,
    this.changeSeq,
    required this.syncState,
    required this.hotelId,
    required this.isActive,
    required this.logicalName,
    required this.label,
    required this.kind,
    required this.protocol,
    this.host,
    this.port,
    this.devicePath,
    this.paperWidthMm,
    this.location,
    this.prepStationId,
    required this.isOnline,
    this.lastHeartbeatAt,
    this.lastError,
    this.fallbackPrinterId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    if (!nullToAbsent || updatedBy != null) {
      map['updated_by'] = Variable<String>(updatedBy);
    }
    if (!nullToAbsent || originDeviceId != null) {
      map['origin_device_id'] = Variable<String>(originDeviceId);
