class PrintJobRow extends DataClass implements Insertable<PrintJobRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String? createdBy;
  final String? updatedBy;
  final String? originDeviceId;
  final int? changeSeq;
  final SyncState syncState;
  final String hotelId;
  final String documentTypeId;
  final String? printerId;
  final String? templateId;

  /// Donnees du document, en JSON.
  final String? payload;

  /// Document deja mis en forme : flux ESC/POS ou PDF.
  final Uint8List? rendered;
  final PrintJobStatus status;
  final int attempts;
  final String? lastError;

  /// Regle R3 : une reimpression est un nouveau travail marque DUPLICATA et
  /// relie a l'original, jamais une reexecution silencieuse du premier. Cela
  /// evite qu'un ticket ressorte deux fois en cuisine sans que personne ne
  /// puisse dire lequel est le bon.
  final bool isDuplicate;
  final String? originalJobId;
  final String? sourceTable;
  final String? sourceId;
  final String? requestedBy;
  final String? requestedFromDeviceId;
  final DateTime? sentAt;
  final DateTime? printedAt;
  const PrintJobRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.createdBy,
    this.updatedBy,
    this.originDeviceId,
    this.changeSeq,
    required this.syncState,
    required this.hotelId,
    required this.documentTypeId,
    this.printerId,
    this.templateId,
    this.payload,
    this.rendered,
    required this.status,
    required this.attempts,
    this.lastError,
    required this.isDuplicate,
    this.originalJobId,
    this.sourceTable,
    this.sourceId,
    this.requestedBy,
    this.requestedFromDeviceId,
    this.sentAt,
    this.printedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    if (!nullToAbsent || updatedBy != null) {
      map['updated_by'] = Variable<String>(updatedBy);
    }
    if (!nullToAbsent || originDeviceId != null) {
      map['origin_device_id'] = Variable<String>(originDeviceId);
    }
    if (!nullToAbsent || changeSeq != null) {
      map['change_seq'] = Variable<int>(changeSeq);
    }
    {
      map['sync_state'] = Variable<String>(
        $PrintJobsTable.$convertersyncState.toSql(syncState),
      );
    }
    map['hotel_id'] = Variable<String>(hotelId);
    map['document_type_id'] = Variable<String>(documentTypeId);
    if (!nullToAbsent || printerId != null) {
      map['printer_id'] = Variable<String>(printerId);
    }
    if (!nullToAbsent || templateId != null) {
